package com.haucheng.erp.service;
import com.haucheng.erp.dto.BrandRequest; import com.haucheng.erp.entity.MdBrand; import com.haucheng.erp.exception.BusinessException; import com.haucheng.erp.mapper.BrandMapper; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service @RequiredArgsConstructor public class BrandService { private final BrandMapper mapper; private final OperationLogService operationLog;
 public List<MdBrand> getAll(){return mapper.selectAll();} public List<MdBrand> getOptions(){return mapper.selectAll().stream().filter(x->Boolean.TRUE.equals(x.getStatus())).toList();} public MdBrand getById(Long id){return require(id);}
 @Transactional public MdBrand create(BrandRequest r){String c=r.getBrandCode().trim(),n=r.getBrandName().trim();unique(c,n,null);MdBrand e=build(r,c,n);mapper.insert(e);operationLog.record("BRAND_CREATE",String.valueOf(e.getId()),"创建品牌");return e;}
 @Transactional public MdBrand update(Long id,BrandRequest r){require(id);String c=r.getBrandCode().trim(),n=r.getBrandName().trim();unique(c,n,id);MdBrand e=build(r,c,n);e.setId(id);mapper.update(e);operationLog.record("BRAND_UPDATE",String.valueOf(id),"修改品牌");return e;}
 @Transactional public void updateStatus(Long id,Boolean status){MdBrand e=require(id);e.setStatus(status);mapper.update(e);operationLog.record(status?"BRAND_ENABLE":"BRAND_DISABLE",String.valueOf(id),status?"启用品牌":"停用品牌");}
 @Transactional public void delete(Long id){require(id);if(mapper.countProducts(id)>0)throw BusinessException.conflict("品牌已被物资使用，不能删除");mapper.deleteById(id);operationLog.record("BRAND_DELETE",String.valueOf(id),"删除品牌");}
 private MdBrand require(Long id){MdBrand e=mapper.selectById(id);if(e==null)throw BusinessException.notFound("品牌不存在");return e;} private void unique(String c,String n,Long id){if(mapper.countByCode(c,id)>0)throw BusinessException.conflict("品牌编号已存在");if(mapper.countByName(n,id)>0)throw BusinessException.conflict("品牌名称已存在");} private MdBrand build(BrandRequest r,String c,String n){MdBrand e=new MdBrand();e.setBrandCode(c);e.setBrandName(n);e.setRemark(r.getRemark());e.setStatus(r.getStatus()==null||r.getStatus());return e;}
}
